<div id="lightbox">
<button id="lightbox-close" style="position:absolute;top:1rem;right:1.5rem;background:none;border:none;color:white;font-size:2.5rem;cursor:pointer;z-index:1;">&times;</button>
<button id="lightbox-prev" style="position:absolute;left:0.5rem;top:50%;transform:translateY(-50%);background:rgba(255,255,255,0.1);border:none;color:white;font-size:2rem;cursor:pointer;padding:0.75rem;z-index:1;">&#8249;</button>
<img id="lightbox-img" src="" alt="" style="max-width:90vw;max-height:85vh;object-fit:contain;">
<button id="lightbox-next" style="position:absolute;right:0.5rem;top:50%;transform:translateY(-50%);background:rgba(255,255,255,0.1);border:none;color:white;font-size:2rem;cursor:pointer;padding:0.75rem;z-index:1;">&#8250;</button>
</div>